
"use client";

import React, { useState, useEffect, useCallback } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { UserCircle2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useToast } from '@/hooks/use-toast';
import { supabase } from '@/lib/supabase/client';
import type { User } from '@supabase/supabase-js';
import { Skeleton } from '@/components/ui/skeleton';
import { useRouter } from 'next/navigation';

export default function ProfilePage() {
    const { toast } = useToast();
    const router = useRouter();
    const [profileData, setProfileData] = useState({ name: '', email: '', phone: '', din: '', address: '' });
    const [loading, setLoading] = useState(true);

    const fetchProfileData = useCallback(async (currentUser: User) => {
        let profile = {
            name: currentUser.user_metadata?.full_name || 'N/A',
            email: currentUser.email || 'N/A',
            phone: currentUser.phone || 'N/A',
            din: 'Not yet assigned',
            address: 'Not available'
        };

        try {
            // Fetch supplemental data from the 'users' table
            const { data: userProfile, error: profileError } = await supabase
                .from('users')
                .select('din, name, phone')
                .eq('uid', currentUser.id)
                .maybeSingle();

            if (profileError) {
                console.error("Error fetching from users table:", profileError.message);
                toast({ title: "Error", description: "Could not fetch DIN from profile.", variant: "destructive" });
            }

            if (userProfile) {
                profile.din = userProfile.din || 'Not yet assigned';
                profile.name = userProfile.name || profile.name;
                profile.phone = userProfile.phone || profile.phone;
            }

            // Fetch address info from the latest application
            const { data: latestAppData, error: appError } = await supabase
                .from('applications')
                .select('data')
                .eq('user_id', currentUser.id)
                .order('created_at', { ascending: false })
                .limit(1)
                .maybeSingle();

            if (appError) {
                console.warn("Could not fetch address from applications:", appError.message);
            }

            if (latestAppData?.data) {
                const appData = latestAppData.data;
                const addressParts = [
                    appData.appHouseNo,
                    appData.appStreetName,
                    appData.appDistrict,
                    appData.appCityTown,
                ].filter(Boolean); // Filter out any undefined/null parts
                
                if (addressParts.length > 0) {
                    profile.address = addressParts.join(', ');
                }
            }
        } catch (error) {
            console.error("A critical error occurred while fetching profile data:", error);
            toast({ title: "Error", description: "Failed to fetch some profile details.", variant: "destructive" });
        } finally {
            setProfileData(profile);
            setLoading(false);
        }
    }, [toast]);

    useEffect(() => {
        const initializeProfile = async () => {
            setLoading(true);
            const { data: { session }, error } = await supabase.auth.getSession();
            if (error || !session) {
                toast({ title: "Authentication Required", description: "Please log in to view your profile.", variant: "destructive" });
                router.push('/login?redirectTo=/dashboard/profile');
                return;
            }
            await fetchProfileData(session.user);
        };
        initializeProfile();
    }, [router, toast, fetchProfileData]);

    const handleActionClick = (actionName: string) => {
        toast({
            title: "Feature In Development",
            description: `${actionName} functionality is not yet implemented.`,
        });
    };
    
    const ProfileItem = ({ label, value, isLoading }: { label: string; value: string | null | undefined; isLoading: boolean }) => (
         <div className="flex flex-col space-y-1">
            <span className="text-sm text-muted-foreground">{label}</span>
            {isLoading ? <Skeleton className="h-5 w-48" /> : <p className="font-medium">{value || 'N/A'}</p>}
        </div>
    );
    
    if (loading) {
        return (
             <div className="space-y-8">
                <CardHeader className="px-0 pt-0">
                    <Skeleton className="h-9 w-64" />
                    <Skeleton className="h-5 w-80" />
                </CardHeader>
                <Card>
                    <CardHeader><Skeleton className="h-6 w-48" /></CardHeader>
                    <CardContent className="space-y-4 pt-6">
                        <ProfileItem label="Full Name" value="" isLoading={true} />
                        <ProfileItem label="Developer Identification Number (DIN)" value="" isLoading={true} />
                        <ProfileItem label="Email Address" value="" isLoading={true} />
                        <ProfileItem label="Phone Number" value="" isLoading={true} />
                        <ProfileItem label="Registered Address" value="" isLoading={true} />
                    </CardContent>
                </Card>
            </div>
        );
    }

    return (
        <div className="space-y-8">
            <CardHeader className="px-0 pt-0">
                <CardTitle className="text-2xl sm:text-3xl font-bold text-primary flex items-center">
                <UserCircle2 className="mr-3 h-7 w-7" /> My Profile
                </CardTitle>
                <CardDescription>
                View and manage your personal information and account settings.
                </CardDescription>
            </CardHeader>
            <Card>
                <CardHeader>
                    <CardTitle>Personal Information</CardTitle>
                    <CardDescription>This information is used for all your applications.</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4 pt-6">
                    <ProfileItem label="Full Name" value={profileData.name} isLoading={loading} />
                    <ProfileItem label="Developer Identification Number (DIN)" value={profileData.din} isLoading={loading} />
                    <ProfileItem label="Email Address" value={profileData.email} isLoading={loading} />
                    <ProfileItem label="Phone Number" value={profileData.phone} isLoading={loading} />
                    <ProfileItem label="Registered Address" value={profileData.address} isLoading={loading} />
                    
                    <div className="pt-4 flex flex-col sm:flex-row gap-2">
                        <Button onClick={() => handleActionClick("Edit Profile")} disabled={loading}>Edit Profile</Button>
                        <Button variant="outline" onClick={() => handleActionClick("Change Password")} disabled={loading}>Change Password</Button>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}
